<!-- ════════ HERO ════════ -->
<header class="hero">
  <div class="container">
    <h1>Nine Decades of Oscar-Winning Scores</h1>
    <p class="subtitle">A historical trend analysis of every Academy Award Best Original Score winner from 1934 through 2026 — 93 ceremonies, 79 composers, and one golden statuette.</p>
